import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD: Long = 998244353L
private const val G: Long = 3L

fun modAdd(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun modSub(a: Long, b: Long): Long {
    var res = a - b
    if (res < 0) res += MOD
    return res
}

fun modMul(a: Long, b: Long): Long = (a * b) % MOD

fun modPow(a: Long, e: Long): Long {
    var base = a
    var exp = e
    var res = 1L
    while (exp > 0) {
        if ((exp and 1L) != 0L) res = modMul(res, base)
        base = modMul(base, base)
        exp = exp shr 1
    }
    return res
}

fun modInv(a: Long): Long = modPow(a, MOD - 2)

fun ntt(a: LongArray, invert: Boolean) {
    val n = a.size
    var j = 0
    for (i in 1 until n) {
        var bit = n shr 1
        while (j and bit != 0) {
            j = j xor bit
            bit = bit shr 1
        }
        j = j xor bit
        if (i < j) {
            val tmp = a[i]
            a[i] = a[j]
            a[j] = tmp
        }
    }
    var len = 2
    while (len <= n) {
        val wlen = if (!invert) {
            modPow(G, (MOD - 1) / len)
        } else {
            modInv(modPow(G, (MOD - 1) / len))
        }
        var i = 0
        while (i < n) {
            var w = 1L
            for (k in 0 until len / 2) {
                val u = a[i + k]
                val v = modMul(a[i + k + len / 2], w)
                a[i + k] = modAdd(u, v)
                a[i + k + len / 2] = modSub(u, v)
                w = modMul(w, wlen)
            }
            i += len
        }
        len = len shl 1
    }
    if (invert) {
        val invN = modInv(n.toLong())
        for (i in 0 until n) {
            a[i] = modMul(a[i], invN)
        }
    }
}

fun convolution(a: LongArray, b: LongArray): LongArray {
    var n = 1
    val need = a.size + b.size - 1
    while (n < need) n = n shl 1
    val fa = LongArray(n)
    val fb = LongArray(n)
    for (i in a.indices) fa[i] = a[i]
    for (i in b.indices) fb[i] = b[i]
    ntt(fa, false)
    ntt(fb, false)
    for (i in 0 until n) fa[i] = modMul(fa[i], fb[i])
    ntt(fa, true)
    return fa.copyOf(need)
}

fun polyMul(a: LongArray, b: LongArray): LongArray = convolution(a, b)

fun polyAdd(a: LongArray, b: LongArray): LongArray {
    val n = maxOf(a.size, b.size)
    val res = LongArray(n)
    for (i in 0 until n) {
        val x = if (i < a.size) a[i] else 0L
        val y = if (i < b.size) b[i] else 0L
        res[i] = modAdd(x, y)
    }
    return res
}

fun polySub(a: LongArray, b: LongArray): LongArray {
    val n = maxOf(a.size, b.size)
    val res = LongArray(n)
    for (i in 0 until n) {
        val x = if (i < a.size) a[i] else 0L
        val y = if (i < b.size) b[i] else 0L
        res[i] = modSub(x, y)
    }
    return res
}

fun polyDeriv(a: LongArray): LongArray {
    if (a.size <= 1) return LongArray(1)
    val n = a.size
    val res = LongArray(n - 1)
    for (i in 1 until n) {
        res[i - 1] = modMul(a[i], i.toLong())
    }
    return res
}

fun polyIntegral(a: LongArray): LongArray {
    val n = a.size
    val res = LongArray(n + 1)
    res[0] = 0L
    for (i in 0 until n) {
        res[i + 1] = modMul(a[i], modInv((i + 1).toLong()))
    }
    return res
}

fun polyInv(a: LongArray, n: Int): LongArray {
    val res = LongArray(n)
    res[0] = modInv(a[0])
    var cur = 1
    while (cur < n) {
        cur = cur shl 1
        val tmp = a.copyOf(minOf(a.size, cur))
        val resCur = res.copyOf(cur)
        val conv = polyMul(resCur, resCur)
        val conv2 = polyMul(conv, tmp)
        val two = 2L
        val resNew = LongArray(cur)
        for (i in 0 until cur) {
            val valTmp = if (i < conv2.size) conv2[i] else 0L
            val v = modSub(modMul(two, if (i < resCur.size) resCur[i] else 0L), valTmp)
            resNew[i] = v
        }
        for (i in 0 until cur) res[i] = resNew[i]
    }
    return res
}

fun polyLog(a: LongArray, n: Int): LongArray {
    val der = polyDeriv(a)
    val inv = polyInv(a, n)
    val mul = polyMul(der, inv)
    val res = polyIntegral(mul)
    return res.copyOf(n)
}

fun polyExp(a: LongArray, n: Int): LongArray {
    val res = LongArray(n)
    res[0] = 1L
    var cur = 1
    while (cur < n) {
        cur = cur shl 1
        val resCur = res.copyOf(cur)
        val logRes = polyLog(resCur, cur)
        val diff = LongArray(cur)
        for (i in 0 until cur) {
            val ai = if (i < a.size) a[i] else 0L
            val li = if (i < logRes.size) logRes[i] else 0L
            diff[i] = modSub(ai, li)
        }
        diff[0] = modAdd(diff[0], 1L)
        val prod = polyMul(resCur, diff)
        for (i in 0 until cur) {
            res[i] = if (i < prod.size) prod[i] else 0L
        }
    }
    return res
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val n = br.readLine().trim().toInt()

    val maxN = n
    val fact = LongArray(maxN + 1)
    val invFact = LongArray(maxN + 1)
    fact[0] = 1L
    for (i in 1..maxN) fact[i] = modMul(fact[i - 1], i.toLong())
    invFact[maxN] = modInv(fact[maxN])
    for (i in maxN downTo 1) {
        invFact[i - 1] = modMul(invFact[i], i.toLong())
    }

    val size = n + 1
    val A = LongArray(size)
    for (k in 1..n) {
        val comb = modMul(fact[n], modMul(invFact[k], invFact[n - k]))
        val sign = if ((k % 2) == 1) 1L else MOD - 1L
        A[k] = modMul(sign, comb)
    }

    val logF = polyLog(A, size)
    val B = LongArray(size)
    for (k in 1..n) {
        B[k] = modMul(logF[k], k.toLong())
    }

    val expB = polyExp(B, size)
    val ans = expB[n]
    println(ans % MOD)
}

