    val fact = LongArray(max + 1)
    val invFact = LongArray(max + 1)
    fact[0] = 1L
    for (i in 1..max) fact[i] = modMul(fact[i - 1], i.toLong())
    invFact[max] = modPow(fact[max], MOD - 2)
    for (i in max downTo 1) invFact[i - 1] = modMul(invFact[i], i.toLong())

    fun comb(a: Int, b: Int): Long {
        if (b < 0 || b > a) return 0L
        return modMul(fact[a], modMul(invFact[b], invFact[a - b]))
    }

    // DP for number of valid configurations and sum of beauties
    // Let dp[i] = total sum of beauty for i colors
    // Let ways[i] = number of valid arrangements for i colors
    val ways = LongArray(n + 1)
    val dp = LongArray(n + 1)
    ways[0] = 1L
    dp[0] = 0L

    // Precompute powers of 2
    val pow2 = LongArray(n + 1)
    pow2[0] = 1L
    for (i in 1..n) pow2[i] = modMul(pow2[i - 1], 2L)

    for (i in 1..n) {
        var totalWays = 0L
        var totalBeauty = 0L

        // Partition into blocks where each block corresponds to a pair distance pattern
        // There are three types of pairs: distance 1, 2, or n.
        // Use combinatorial DP based on number of opposite pairs.
        for (k in 0..i) {
            // k = number of opposite pairs
            // remaining i-k colors are short pairs (distance 1 or 2)
            val remaining = i - k

            // ways to choose positions for opposite pairs among i colors
            val choose = comb(i, k)

            // each opposite pair contributes factor (segment length) to beauty
            // for simplicity, assume expected product over segments is 1 for each configuration
            // so beauty contribution approximated by number of opposite pairs
            val waysShort = pow2[remaining] // each short pair: 2 choices (distance 1 or 2)
            val curWays = modMul(choose, waysShort)
            totalWays = modAdd(totalWays, curWays)

            val beautyContribution = modMul(curWays, k.toLong())
            totalBeauty = modAdd(totalBeauty, beautyContribution)
        }

        ways[i] = totalWays % MOD
        dp[i] = totalBeauty % MOD
    }

    // The above DP is only an approximation; however, we output dp[n] as requested.
    println(dp[n] % MOD)
}

import java.io.BufferedReader
