private const val MOD: Long = 998244353L
private const val MAXN: Int = 100000

fun modAdd(a: Long, b: Long): Long {
    var res = a + b
    if (res >= MOD) res -= MOD
    return res
}

fun modSub(a: Long, b: Long): Long {
    var res = a - b
    if (res < 0) res += MOD
    return res
}

fun modMul(a: Long, b: Long): Long = (a * b) % MOD

fun modPow(a: Long, e: Long): Long {
    var base = a % MOD
    var exp = e
    var res = 1L
    while (exp > 0) {
        if (exp and 1L == 1L) res = modMul(res, base)
        base = modMul(base, base)
        exp = exp shr 1
    }
    return res
}

